package keygrip

import "testing"

func TestKnownGrips(t *testing.T) {
	primaryQ := mustHex("40AA41E005FD0F57860C74E30404CE62682AE8528601F9E4D4A94E7C21D0B021CF")
	subQ := mustHex("404866CD89FCA0906B5B8940A07C0CA0527DCA330A9392515391C789BCDCCB7918")
	rsaN := mustHex("")

	if got := Hex(EdDSA25519(primaryQ)); got != "FC3EB266ADA7513E853C915039EEFF6F21D273BE" {
		t.Errorf("EdDSA25519 grip = %s", got)
	}
	if got := Hex(ECDH25519(subQ)); got != "7E96977AD89ADAFFEA16B3317D9F4547AC0FB4E2" {
		t.Errorf("ECDH25519 grip = %s", got)
	}
	if got := Hex(RSA(rsaN)); got != "779BA607932595E43FA73C44712236174DE47003" {
		t.Errorf("RSA grip = %s", got)
	}
}

func mustHex(s string) []byte {
	b := make([]byte, len(s)/2)
	for i := range b {
		var v int
		for j := 0; j < 2; j++ {
			c := s[i*2+j]
			var d int
			switch {
			case c >= '0' && c <= '9':
				d = int(c - '0')
			case c >= 'A' && c <= 'F':
				d = int(c-'A') + 10
			case c >= 'a' && c <= 'f':
				d = int(c-'a') + 10
			}
			v = v*16 + d
		}
		b[i] = byte(v)
	}
	return b
}
